#!/usr/bin/env node
"use strict";

const fs = require("fs");
const path = require("path");

const TERM = "TODO";

function countOccurrences(text, term) {
  if (!term) return 0;
  let count = 0;
  let index = text.indexOf(term);
  while (index !== -1) {
    count += 1;
    index = text.indexOf(term, index + term.length);
  }
  return count;
}

function main() {
  const target = process.argv[2] || "README.md";
  const filePath = path.resolve(process.cwd(), target);

  let text;
  try {
    text = fs.readFileSync(filePath, "utf8");
  } catch (err) {
    process.stderr.write(`无法读取文件: ${target}\n`);
    process.exit(1);
  }

  process.stdout.write(`${countOccurrences(text, TERM)}\n`);
}

main();

